sited.script:

const baseUrl = "https://gimy.com.tw";

function home_list_parse(url, html){
    const $ = cheerio.load(html);
    let list = [];
    $('div.layout-box.clearfix').each(function() {
        const $$ = cheerio.load($(this).html());
        const group_name_raw = $$('div.box-title h3').text().trim();
        if (group_name_raw) {
            const group_name = gbk2big5.traditionalized(group_name_raw);
            $$('li.col-md-2.col-sm-3.col-xs-4').each(function() {
                const $$$ = cheerio.load($(this).html());
                const link = $$$('a.video-pic');
                const videoUrl = link.attr('href');
                const name = link.attr('title');
                const logo = link.attr('data-original');
                if (videoUrl && name) {
                    list.push({
                        group: group_name,
                        url: baseUrl + videoUrl,
                        name: gbk2big5.traditionalized(name),
                        logo: baseUrl + logo
                    });
                }
            });
        }
    });
    return JSON.stringify(list);
}

function list_parse(url, html){
    const $ = cheerio.load(html);
    let list = [];
    $('div.box-video-list li.col-md-2.col-sm-3.col-xs-4').each(function() {
        const $$ = cheerio.load($(this).html());
        const link = $$('a.video-pic');
        const videoUrl = link.attr('href');
        const name = link.attr('title');
        const logo = link.attr('data-original');
        if (videoUrl && name) {
            list.push({
                url: baseUrl + videoUrl,
                name: gbk2big5.traditionalized(name),
                logo: baseUrl + logo
            });
        }
    });
    return JSON.stringify(list);
}

function search_parse(url, html){
    const $ = cheerio.load(html);
    let list = [];
    $('div.details-info-min').each(function() {
        const $$ = cheerio.load($(this).html());
        const link = $$('a.video-pic');
        const videoUrl = link.attr('href');
        const name = link.attr('title');
        const logo = link.attr('data-original');
        if (videoUrl && name) {
            list.push({
                url: baseUrl + videoUrl,
                name: gbk2big5.traditionalized(name),
                logo: baseUrl + logo
            });
        }
    });
    return JSON.stringify(list);
}

function book_parse(url, html) {
    const $ = cheerio.load(html);
    let sections = [];
    $('div.playlist').each(function() {
        const $$ = cheerio.load($(this).html());
        const group = $$('.gico').text().trim();
        $$('.clearfix a').each(function() {
            const episodeLink = $$(this);
            const episodeUrl = episodeLink.attr('href');
            if (episodeUrl && episodeUrl.includes('/video/')) {
                sections.push({
                    group: gbk2big5.traditionalized(group),
                    name: gbk2big5.traditionalized(episodeLink.text().trim()),
                    url: baseUrl + episodeUrl
                });
            }
        });
    });

    let logoUrl = null;
    const bgStyle = $('a.video-pic').attr('style');
    if (bgStyle) {
        const match = bgStyle.match(/url\((.*?)\)/);
        if (match && match[1]) {
            logoUrl = match[1];
        }
    }

    const intro_default = $('span.details-content-default').text();
    const intro_all = $('span.details-content-all').text();
    const intro = intro_all || intro_default;

    const book = {
        name: gbk2big5.traditionalized($('h1.text-overflow').text().trim()),
        logo: baseUrl + logoUrl,
        intro: gbk2big5.traditionalized(intro.replace('線上看:', '').trim()),
        sections: sections
    };

    return JSON.stringify(book);
}

function section_parse(url, html) {
    return JSON.stringify({
        type: "webview",
        data: url
    });
}

sited.WebViewInjection:

javascript:(function() {
    function cleanupAndMaximizePlayer() {
        try {
            const player = document.getElementById('zanpiancms_player');
            if (player) {
                // 將播放器從原始位置取出
                const playerParent = player.parentNode;
                playerParent.removeChild(player);

                // 清空整個 body
                document.body.innerHTML = '';

                // 將播放器重新加回 body
                document.body.appendChild(player);

                // 設置樣式使其全螢幕
                document.body.style.margin = '0';
                document.body.style.padding = '0';
                document.body.style.overflow = 'hidden';
                player.style.position = 'absolute';
                player.style.top = '0';
                player.style.left = '0';
                player.style.width = '100vw';
                player.style.height = '100vh';

                return true; // 表示已成功執行
            }
            return false; // 播放器未找到
        } catch (e) {
            return false;
        }
    }

    let attempts = 0;
    const maxAttempts = 20; // 最多嘗試 10 秒
    const intervalId = setInterval(function() {
        attempts++;
        // 如果清理成功，或達到最大嘗試次數，就停止
        if (cleanupAndMaximizePlayer() || attempts >= maxAttempts) {
            clearInterval(intervalId);
        }
    }, 500); // 每 0.5 秒嘗試一次
})();
